function countRoutes(grid: number[][]): number {
  const m = grid.length, n = grid[0].length, MOD = 1_000_000_007;
  const go = (i: number, j: number): number => {
    if (i >= m || j >= n || grid[i][j] === 1) return 0;
    if (i === m - 1 && j === n - 1) return 1;
    return (go(i + 1, j) + go(i, j + 1)) % MOD;
  };
  return go(0, 0);
}

