function countRoutes(grid: number[][]): number {
  const n = grid[0].length, MOD = 1_000_000_007;
  const row = new Array(n).fill(0);
  row[0] = grid[0][0] === 0 ? 1 : 0;
  for (const cells of grid)
    for (let j = 0; j < n; j++) {
      if (cells[j] === 1) row[j] = 0;
      else if (j > 0) row[j] = (row[j] + row[j - 1]) % MOD;
    }
  return row[n - 1];
}

